from math import gcd

def get_max_triples(n):
    a = [i * i - i + 1 for i in range(1, n + 1)]
    triples = []

    for i in range(1, n):
        for j in range(i + 1, n):
            for k in range(j + 1, n):
                if gcd(a[i] + a[j] + a[k], 3) != 1:
                    triples.append((a[i], a[j], a[k]))

    return len(triples)
